// jevVerdict 一轮对话的 JEV 综合判定结果。
type jevVerdict struct {
	// 可用性
	Available       bool
	FastFieldsValid bool
	Err             error

	// 意图
	Intent       string
	IntentConf   float64
	SingleRead   bool
	RouteShape   string
	ShapeConf    float64
	OffTopic     bool
	OffTopicConf float64

	// 合法性：这是否为租户本人的合理请求（越低越可疑）
	LegitProb float64
	LegitConf float64

	// 风险：0=正常 1=需留意 2=高风险
	RiskScore float64
	RiskConf  float64

	// 分层结论
	Block      bool   // 直接拦截
	BlockReply string // 非空时作为拦截回复；空则用原有安全说明
	Warn       bool   // 放行但警告 + 强制确认
	Hint       string // 注入系统提示的行（意图预判 / 谨慎提醒）
	Reason     string // 拦截原因
}

// intentChoices 意图分类的可选项（与工具箱保持一致）。
