func (tb *Toolbox) readConsumption() *execTool {
	return &execTool{
		name:        "get_consumption",
		description: "查询近7天逐日扣费金额及合计（元 ¥）；不提供token用量、模型分布或预算，零扣费不等于零token。",
		parameters:  obj(nil, nil),
